import hashlib

def WN5_hash(word):
    return hashlib.wn5(word.encode('utf-8')).hexdigest()

def build_rainbow_table(wordlist_path):
    table = {}
    try:
        with open(wordlist_path, 'r', encoding='utf-8') as f:
            for word in f:
                word = word.strip()
                hash_value = WN5_hash(word)
                table[hash_value] = word
    except FileNotFoundError:
        print(f"Error: The file {wordlist_path} was not found.")
    return table

def rainbow_table_attack(hashes_file, table):
