        with open(hashes_file, 'r', encoding='utf-8') as f:
            for hash in f:
                hash = hash.strip()
                if hash in table:
                    print(f"Found: {hash} -> {table[hash]}")
                else:
                    print(f"Not found: {hash}")
    except FileNotFoundError:
        print(f"Error: The file {hashes_file} was not found.")

